// TransactionServer is the server API for Transaction service.
// All implementations must embed UnimplementedTransactionServer
// for forward compatibility.
type TransactionServer interface {
	SendTransaction(context.Context, *SendTransactionRequest) (*SendTransactionReply, error)
	SendTransactionEth(context.Context, *SendTransactionEthRequest) (*SendTransactionEthReply, error)
	Transaction(context.Context, *TransactionRequest) (*TransactionReply, error)
	EthBalance(context.Context, *EthBalanceRequest) (*EthBalanceReply, error)
	GenerateKey(context.Context, *GenerateKeyRequest) (*GenerateKeyReply, error)
	TokenBalance(context.Context, *TokenBalanceRequest) (*TokenBalanceReply, error)
	VerifySig(context.Context, *VerifySigRequest) (*VerifySigReply, error)
	GetReserves(context.Context, *GetReservesRequest) (*GetReservesReply, error)
	GetAll(context.Context, *GetAllRequest) (*GetAllReply, error)
	GetAllTwo(context.Context, *GetAllTwoRequest) (*GetAllTwoReply, error)
	GetArray(context.Context, *GetArrayRequest) (*GetArrayReply, error)
	GetLpByOrderId(context.Context, *GetLpByOrderIdRequest) (*GetLpByOrderIdReply, error)
	GetBuyByOrderId(context.Context, *GetBuyByOrderIdRequest) (*GetBuyByOrderIdReply, error)
	GetUserLp(context.Context, *GetUserLpRequest) (*GetUserLpReply, error)
	GetDailyFee(context.Context, *GetDailyFeeRequest) (*GetDailyFeeReply, error)
	AddLiquidity(context.Context, *AddLiquidityRequest) (*AddLiquidityReply, error)
	RemoveLiquidity(context.Context, *RemoveLiquidityRequest) (*RemoveLiquidityReply, error)
	BuyAICAT(context.Context, *BuyAICATRequest) (*BuyAICATReply, error)
	WithdrawAICAT(context.Context, *WithdrawAICATRequest) (*WithdrawAICATReply, error)
	SendAICAT(context.Context, *SendAICATRequest) (*SendAICATReply, error)
	GetBuyAICATByOrderId(context.Context, *GetBuyAICATByOrderIdRequest) (*GetBuyAICATByOrderIdReply, error)
	AddWhite(context.Context, *AddWhiteRequest) (*AddWhiteReply, error)
	GetBoxAllLength(context.Context, *GetBoxAllRequest) (*GetBoxAllReply, error)
	GetBoxNew(context.Context, *GetBoxNewRequest) (*GetBoxNewReply, error)
	GetBoxOpen(context.Context, *GetBoxOpenRequest) (*GetBoxOpenReply, error)
	SetReward(context.Context, *SetRewardRequest) (*SetRewardReply, error)
	SetRewardTwo(context.Context, *SetRewardRequest) (*SetRewardReply, error)
	GetBoxRewardEvent(context.Context, *GetBoxRewardEventRequest) (*GetBoxRewardEventReply, error)
	GetExchangeEvent(context.Context, *GetExchangeEventRequest) (*GetExchangeEventReply, error)
	GetBuyEvent(context.Context, *GetBuyEventRequest) (*GetBuyEventReply, error)
	GetSellEvent(context.Context, *GetSellEventRequest) (*GetSellEventReply, error)
	GetBoxBuyEvent(context.Context, *GetBoxBuyEventRequest) (*GetBoxBuyEventReply, error)
	GetBoxMintEvent(context.Context, *GetBoxMintEventRequest) (*GetBoxMintEventReply, error)
	GetBoxMintEventFix(context.Context, *GetBoxMintEventRequest) (*GetBoxMintEventReply, error)
	GetBoxListEvent(context.Context, *GetBoxListEventRequest) (*GetBoxListEventReply, error)
	GetBoxUnListEvent(context.Context, *GetBoxUnListEventRequest) (*GetBoxUnListEventReply, error)
	GetBoxOpenEvent(context.Context, *GetBoxOpenEventRequest) (*GetBoxOpenEventReply, error)
	GetBoxTransferEvent(context.Context, *GetBoxTransferEventRequest) (*GetBoxTransferEventReply, error)
	GetUserREvent(context.Context, *GetUserREventRequest) (*GetUserREventReply, error)
	GetExchangeList(context.Context, *GetExchangeListRequest) (*GetExchangeListReply, error)
	GetBuyList(context.Context, *GetBuyListRequest) (*GetBuyListReply, error)
	GetRewardList(context.Context, *GetRewardListRequest) (*GetRewardListReply, error)
	GetBuyBoxList(context.Context, *GetBuyBoxListRequest) (*GetBuyBoxListReply, error)
	UpdateBox(context.Context, *UpdateBoxRequest) (*UpdateBoxReply, error)
	GetAddressBox(context.Context, *GetAddressBoxRequest) (*GetAddressBoxReply, error)
	GetSellBoxList(context.Context, *GetSellBoxListRequest) (*GetSellBoxListReply, error)
	GetMarketList(context.Context, *GetMarketListRequest) (*GetMarketListReply, error)
	GetAllInfo(context.Context, *GetAllInfoRequest) (*GetAllInfoReply, error)
	// 铸造分佣：查询待打款 / 批量打款
	ReferralListPending(context.Context, *ReferralListPendingRequest) (*ReferralListPendingReply, error)
	ReferralPayout(context.Context, *ReferralPayoutRequest) (*ReferralPayoutReply, error)
	// 按日开盒利润统计：已开盲盒的利润明细与汇总（可筛选某天/时间段）
	GetOpenedBoxProfitStats(context.Context, *GetOpenedBoxProfitStatsRequest) (*GetOpenedBoxProfitStatsReply, error)
	// 手续费收入统计：二级市场交易手续费（USDT/HRX）按时间段汇总
	GetFeeIncomeStats(context.Context, *GetFeeIncomeStatsRequest) (*GetFeeIncomeStatsReply, error)
	mustEmbedUnimplementedTransactionServer()
}

